def _normalize_enum_value(value: str) -> str:
    return ''.join(ch for ch in value.upper() if ch.isalnum())


def _enum_member_name(value: str) -> str:
    name = re.sub(r'[^A-Z0-9]+', '_', value.upper()).strip('_')
    name = re.sub(r'(?<=\d)(?=[A-Z])', '_', name)
    if not name or name[0].isdigit() or keyword.iskeyword(name):
        name = f'ENUM_{name}'
    return name


def _build_enum(enum_name: str, enum_values: dict[str, str]) -> type[Enum]:
    namespace = CaseInsensitiveEnumMeta.__prepare__(enum_name, (str, Enum))
    namespace['__module__'] = __name__
    namespace['__doc__'] = f'Type of {enum_name}.'
    for normalized_name, wire_value in enum_values.items():
        if normalized_name.isidentifier() and not keyword.iskeyword(normalized_name):
            namespace[normalized_name] = wire_value
        safe_name = _enum_member_name(wire_value)
        if safe_name not in namespace:
            namespace[safe_name] = wire_value
    return CaseInsensitiveEnumMeta(enum_name, (str, Enum), namespace)


_ENUM_CLASSES = {name: _build_enum(name, values) for name, values in _ENUM_VALUES.items()}
globals().update(_ENUM_CLASSES)


def __getattr__(name: str) -> type[Enum]:
    try:
        return _ENUM_CLASSES[name]
    except KeyError as exc:
        raise AttributeError(f'module {__name__!r} has no attribute {name!r}') from exc
